bool write_off(const gsSurfMesh& mesh, const std::string& filename)
{
    typedef gsSurfMesh::Point Point;
    typedef gsSurfMesh::Normal Normal;
    FILE* out = fopen(filename.c_str(), "w");
    if (!out)
        return false;


    bool  has_normals   = false;
    bool  has_texcoords = false;
    bool  has_colors = false;
    bool  has_sharp = false;
    gsSurfMesh::Vertex_property<Normal> normals = mesh.get_vertex_property<Normal>("v:normal");
    gsSurfMesh::Vertex_property<Point>  texcoords = mesh.get_vertex_property<Point>("v:texcoord");
    gsSurfMesh::Vertex_property<Point> colors = mesh.get_vertex_property<Point>("v:color");
    gsSurfMesh::Halfedge_property<bool> sharp = mesh.get_halfedge_property<bool>("h:sharp");
    if (normals)   has_normals = true;
    if (texcoords) has_texcoords = true;
    if (colors) has_colors = true;
    if (sharp) has_sharp = true;


    // header
    if(has_texcoords)
        fprintf(out, "ST");
    if(has_colors)
        fprintf(out, "C");
    if(has_normals)
        fprintf(out, "N");
    fprintf(out, "OFF\n%d %d 0\n", mesh.n_vertices(), mesh.n_faces());


    // vertices, and optionally normals and texture coordinates
    gsSurfMesh::Vertex_property<Point> points = mesh.get_vertex_property<Point>("v:point");
    for (gsSurfMesh::Vertex_iterator vit=mesh.vertices_begin(); vit!=mesh.vertices_end(); ++vit)
    {
        const Point& p = points[*vit];
        fprintf(out, "%.10f %.10f %.10f", cast<real_t,double>(p[0]), cast<real_t,double>(p[1]), cast<real_t,double>(p[2]));

        if (has_normals)
        {
            const Normal& n = normals[*vit];
            fprintf(out, " %.10f %.10f %.10f", cast<real_t,double>(n[0]), cast<real_t,double>(n[1]), cast<real_t,double>(n[2]));
        }

        if (has_colors)
        {
            const Point& c = colors[*vit];
            fprintf(out, " %.10f %.10f %.10f", cast<real_t,double>(c[0]), cast<real_t,double>(c[1]), cast<real_t,double>(c[2]));
        }

        if (has_texcoords)
        {
            const Point& t = texcoords[*vit];
            fprintf(out, " %.10f %.10f", cast<real_t,double>(t[0]), cast<real_t,double>(t[1]));
        }

        fprintf(out, "\n");
    }


    // faces
    for (gsSurfMesh::Face_iterator fit=mesh.faces_begin(); fit!=mesh.faces_end(); ++fit)
    {
        int nV = mesh.valence(*fit);
        fprintf(out, "%d", nV);
        gsSurfMesh::Vertex_around_face_circulator fvit=mesh.vertices(*fit), fvend=fvit;
        do
        {
            fprintf(out, " %d", (*fvit).idx());
        }
        while (++fvit != fvend);
        fprintf(out, "\n");
    }

    // sharp edges 
    if (has_sharp){
        for (gsSurfMesh::Edge_iterator it = mesh.edges_begin();
            it != mesh.edges_end();
            ++it)
        {
            auto e = *it;
            auto v1 = mesh.vertex(e, 0);
            auto v2 = mesh.vertex(e, 1);

            if (sharp[mesh.halfedge(e, 0)]){
                fprintf(out, "%d %d\n", v1.idx(), v2.idx());
            }
        }
    }

    fclose(out);
    return true;
}

