        for (auto it = block.begin(j); it; ++it)
        {
            result.insertTo(it.row(), j, it.value());
            result.insertTo(brows+it.row(), bcols+j, it.value());
            result.insertTo(2*brows+it.row(), 2*bcols+j, it.value());
        }
      }
      result.makeCompressed();
    }

